package org.marketreview.nativeapp;
import org.json.*;import java.util.*;
final class MaterialLibraryModel {
 static void require(boolean b,String why){if(!b)throw new IllegalArgumentException(why);}
 static String json(Object o)throws Exception{return EvidenceReviewModel.json(o);}
 static String fingerprint(Object o)throws Exception{return EvidenceReviewModel.fingerprint(o);}
 static JSONObject obj(JSONObject o,String k){return EvidenceReviewModel.obj(o,k);}
 static JSONArray arr(JSONObject o,String k){return EvidenceReviewModel.arr(o,k);}
 static String text(JSONObject o,String k,String old){String s=o.optString(k);return !s.isEmpty()?s:obj(o,"legacyOriginal").optString(old);}
 static String key(JSONObject ref)throws Exception{return ref.getString("kind")+":"+ref.getString("id")+":"+fingerprint(ref);}
 static JSONObject material(JSONObject d)throws Exception{String kind=d.optString("kind");JSONObject raw=obj(d,"row");require(d.opt("id") instanceof String&&raw.opt("id") instanceof String&&(kind.equals("docs")||kind.equals("collections"))&&!d.optString("id").isEmpty()&&d.optString("id").equals(raw.optString("id")),"需精确来源类型和原生ID");json(raw);JSONObject copy=SourceAnalysisPacket.copy(raw).put("sourceKind",kind),snap=SourceAnalysisPacket.snapshot(copy);JSONObject ref=new JSONObject().put("kind",kind).put("id",raw.get("id")).put("snapshot",snap).put("bodyHash",SourceAnalysisPacket.hash(raw.optString("text")+'\0'+raw.optString("originalText"))).put("rowFingerprint",fingerprint(raw));JSONObject old=obj(raw,"legacyOriginal");Object tags=raw.optJSONArray("tags")!=null?raw.get("tags"):old.opt("tags"),sectors=raw.optJSONArray("sectors")!=null?raw.get("sectors"):old.opt("sectors");if(tags==null&&old.opt("tags_json") instanceof String)tags=old.get("tags_json");String type=text(raw,"sourceType","source_type");if(type.isEmpty())type=text(raw,"type","type");String source=text(raw,"author","author");if(source.isEmpty())source=snap.optString("author");return new JSONObject().put("reference",ref).put("title",raw.opt("title")==null?JSONObject.NULL:raw.get("title")).put("source",source.isEmpty()?"未知":source).put("type",type.isEmpty()?"未知":type).put("topic",raw.optString("topic").isEmpty()?"未知":raw.optString("topic")).put("publishedAt",snap.optString("publishedAt")).put("originalTags",tags==null?JSONObject.NULL:tags).put("originalSectors",sectors==null?JSONObject.NULL:sectors).put("verification",raw.opt("verification")==null?JSONObject.NULL:raw.get("verification"));}
 static JSONArray materials(JSONArray input)throws Exception{Set<String> ids=new HashSet<>();JSONArray out=new JSONArray();for(int i=0;i<input.length();i++){JSONObject m=material(input.getJSONObject(i)),ref=m.getJSONObject("reference");require(ids.add(ref.getString("kind")+":"+ref.getString("id")),"同来源类型原生ID重复");out.put(m);}return out;}
 static JSONObject resolve(JSONObject ref,JSONArray descriptors)throws Exception{JSONArray rows=new JSONArray();int found=0;for(int i=0;i<descriptors.length();i++){JSONObject d=descriptors.getJSONObject(i);if(d.optString("kind").equals(ref.optString("kind"))){JSONObject raw=d.getJSONObject("row");if(raw.optString("id").equals(ref.optString("id"))){require(d.optString("id").equals(ref.optString("id")),"来源描述符身份不符");found++;}rows.put(raw);}}require(found==1,"当前来源缺失或身份重复");JSONObject current=SourceAnalysisPacket.exactSource(ref,rows);require(fingerprint(current).equals(ref.optString("rowFingerprint")),"完整来源版本已改变；历史快照保留，拒绝替代版本");return current;}
 static JSONArray filter(JSONArray input,JSONObject q,JSONObject heads)throws Exception{List<JSONObject> selected=new ArrayList<>();String search=q.optString("search").trim().toLowerCase(Locale.ROOT);for(int i=0;i<input.length();i++){JSONObject m=input.getJSONObject(i),c=obj(heads,key(m.getJSONObject("reference")));boolean match=true;for(String k:new String[]{"source","topic","type"})if(!q.optString(k).isEmpty()&&!q.optString(k).equals(m.optString(k)))match=false;String category=c.optString("category");if(category.isEmpty())category="未分类";if(!q.optString("category").isEmpty()&&!q.optString("category").equals(category))match=false;if(match&&(search.isEmpty()||json(m).toLowerCase(Locale.ROOT).contains(search)||json(c).toLowerCase(Locale.ROOT).contains(search)))selected.add(m);}boolean earliest=q.optString("order").equals("earliest");selected.sort((a,b)->{Long aa=time(a.optString("publishedAt")),bb=time(b.optString("publishedAt"));if(aa==null||bb==null)return aa==null?(bb==null?0:1):-1;return earliest?aa.compareTo(bb):bb.compareTo(aa);});return new JSONArray(selected);}
 static Long time(String s){try{return java.time.OffsetDateTime.parse(s).toInstant().toEpochMilli();}catch(Exception e){try{return java.time.LocalDate.parse(s).toEpochDay()*86400000L;}catch(Exception ignored){return null;}}}
 static JSONObject classification(JSONObject ref,String category,JSONArray tags,String notes,String parent)throws Exception{JSONObject snap=obj(ref,"snapshot");require((ref.optString("kind").equals("docs")||ref.optString("kind").equals("collections"))&&!ref.optString("id").isEmpty()&&ref.optString("id").equals(snap.optString("id"))&&snap.optString("sourceKind").equals(ref.optString("kind"))&&ref.optString("bodyHash").equals(SourceAnalysisPacket.hash(snap.optString("text")+'\0'+snap.optString("originalText")))&&ref.optString("rowFingerprint").matches("[a-f0-9]{64}"),"来源引用版本无效");require(category.length()<=200&&tags.length()<=30,"分类/标签超过边界");Set<String> unique=new HashSet<>();for(int i=0;i<tags.length();i++){require(tags.get(i) instanceof String&&!tags.getString(i).trim().isEmpty()&&tags.getString(i).length()<=200&&unique.add(tags.getString(i)),"标签无效或重复，未静默删改");}JSONObject r=new JSONObject().put("kind","classification").put("reference",ref).put("category",category).put("tags",tags).put("notes",notes).put("parentId",parent).put("verification","human-label-unverified");r.put("id","classification:"+fingerprint(r));json(r);return r;}
 static JSONObject validate(JSONObject r)throws Exception{JSONObject expected=classification(obj(r,"reference"),r.optString("category"),arr(r,"tags"),r.optString("notes"),r.optString("parentId"));require(EvidenceReviewModel.canonical(r).equals(EvidenceReviewModel.canonical(expected)),"分类记录与原文/身份指纹不符");return r;}
 static String read(JSONObject m,JSONObject c)throws Exception{JSONObject ref=obj(m,"reference"),snap=obj(ref,"snapshot");return m.optString("title")+"\n来源身份："+ref.optString("kind")+" / "+ref.optString("id")+"\n版本："+ref.optString("rowFingerprint")+"\n来源："+m.optString("source")+" · 类型："+m.optString("type")+" · 原主题："+m.optString("topic")+"\n原时点："+m.optString("publishedAt")+"\n原资料核验声明："+(m.optString("verification").isEmpty()?"未知":m.optString("verification"))+"（本页未重新验收）\n分类为人工标签，不证明产业/公司归属或证据事实。\n\n完整保留本机正文（不代表媒体原始全文已核验）\n"+snap.optString("text")+"\n\n原始正文\n"+snap.optString("originalText")+"\n\n原标签/板块\n"+json(new JSONObject().put("tags",m.opt("originalTags")).put("sectors",m.opt("originalSectors")))+"\n\n此版本人工分类\n"+json(c);}
}





